sys_variable_value.value:
(function execute(inputs, outputs) {
   
        var applicationForm = JSON.parse(inputs.input);
        outputs.test = applicationForm.first_applicant.employer;

        var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');

        if (gr.get(inputs.sysId)) {
            gr.are_you_a_us_citizen = applicationForm.first_applicant.are_you_a_us_citizen;
            gr.us_tax_identification_number = applicationForm.first_applicant.us_tax_identification_number;
            gr.are_you_a_resident_of_a_country_other_than_uk = applicationForm.first_applicant.are_you_a_resident_of_a_country_other_than_uk_for_tax_purpose;
            gr.non_uk_tax_identification_number = applicationForm.first_applicant.non_uk_tax_identification_number;
            gr.employment_status = applicationForm.first_applicant.employment_status;
            gr.employment_industry = applicationForm.first_applicant.employment_industry;
            gr.occupation = applicationForm.first_applicant.occupation;
            gr.source_of_initial_deposit = applicationForm.first_applicant.source_of_deposit;
            gr.state_purpose_of_opening_account = applicationForm.first_applicant.what_are_you_saving_for;
            gr.annual_income_before_tax = applicationForm.first_applicant.annual_income_before_tax;
            gr.years_at_address = applicationForm.first_applicant.years_at_address;
            gr.employer = applicationForm.first_applicant.employer;
            gr.ach_withdrawal = applicationForm.first_applicant.ach_withdrawal;
            gr.ach_deposit = applicationForm.first_applicant.ach_deposit;
            gr.atm_deposit = applicationForm.first_applicant.atm_deposit;
            gr.atm_withdrawal = applicationForm.first_applicant.atm_withdrawal;
            gr.cheque_deposit = applicationForm.first_applicant.cheque_deposit;
            gr.cheque_withdrawal = applicationForm.first_applicant.cheque_withdrawal;
            gr.cash_deposit = applicationForm.first_applicant.cash_deposit;
            gr.cash_withdrawal = applicationForm.first_applicant.cash_withdrawal;
            //gr.mobile = applicationForm.first_applicant.mobile_number;
            //gr.mobile_contact = applicationForm.first_applicant.mobile_number;
            //gr.home_contact = applicationForm.first_applicant.mobile_number;
            gr.update();
        } else {
            gs.error("No record found with sys_id: " + inputs.sysId);
        }

})(inputs, outputs);

